function expandPP(spath,title,year){if(!spath)
return"";if(!isNaN(spath)){return"./posters/"+spath;}
var fpath="";if(spath.indexOf('@')===0){fpath+='commons/thumb/';spath=spath.slice(1);}else{fpath+='en/thumb/';}
fpath+=spath[0]+"/"+spath[1]+spath[2]+"/";spath=spath.slice(3);fpath+=spath.replace("&",title.replaceAll(" ","_"),).replaceAll("=","poster").replaceAll("!","Poster").replaceAll("+","film").replaceAll(",","Film").replace("*",".jpg").replaceAll("<","movie").replaceAll(">","Movie").replace("^",".JPG").replace("?",".jpeg").replaceAll("~",year);return"https://upload.wikimedia.org/wikipedia/"+fpath+"/220px-"+fpath.split("/").slice(-1);}
var tooltip=function(ele){var n;var i;var h=false;if(!(window.innerWidth<1024)){(n=ele.tooltipster({contentAsHTML:true,updateAnimation:false,arrow:false,side:["right","left"],interactive:true,delay:200,minWidth:320,maxWidth:320,content:"Loading..",functionBefore:function(n,t){if(!h){h=true;$.ajax("tooltips/".concat(ele.data("tip")),{dataType:"html"}).done(function(t){return n.content(t);});}},functionPosition:function(t,n,i){if("left"===i.side){i.coord.left+=0.5*n.geo.origin.size.width;}else{i.coord.left-=0.5*n.geo.origin.size.width;}
i.coord.top-=(n.geo.origin.size.height-i.size.height)/2;i.coord.top+=0.5*n.geo.origin.size.height;return i;}}).tooltipster("instance")).on("before",i=function(){setTimeout(function(){try{$(ele.tooltipster("elementTooltip")).activate();}catch(t){}},10);});n.on("updated",i);}}
let movies=[];let allMovies=[];moviedb.forEach(mo=>{mo[4]=mo[4].split("|").map(m=>!isNaN(m)?actorsFreq[m]:m);mo[5]=mo[5].split("|").map(m=>!isNaN(m)?dirFreq[m]:m);mo[2]=mo[2].split("|").map(m=>genres[m]);mo[1]=mo[1]>=24?1900+mo[1]:2000+mo[1];if(mo.length==7)
{mo.push('');}else{mo[7]=expandPP(mo[7],mo[0],mo[1]);}
if(mo.length==8)
{mo.push(0);}
let movie={};props.forEach(p=>{movie[p]=mo[props.indexOf(p)];})
movie.tooltip=movie.original_title.replaceAll(' ','').replace(/[^a-zA-Z 0-9]+/g,'')+movie.year_of_release;movies.push(movie);});allMovies=sort([...movies],"imdb_rating");document.getElementById("searchAll").addEventListener("keydown",function(event){if(event.key==="Enter"&&document.getElementById("searchAll").value){event.preventDefault();searchAll();}});function renderPage(page){document.getElementById("cards").innerHTML='';if(!page||!page.length){document.getElementById("cards").insertAdjacentHTML('beforeend',"<h3>No Results</h3>");}else{page.forEach(d=>document.getElementById("cards").insertAdjacentHTML('beforeend',getNewDivTemplate(d)));document.querySelectorAll('.tooltipstered').forEach(e=>tooltip($(e)));}}
function getNewDivTemplate(mov){var div=`<div class="movie-item item"><div class="item-inner"><a class="cover tooltipstered"data-tip="${mov.tooltip}"onclick="openYT('${mov.yt}','${mov.tplus}','${mov.original_title}');"><div><img class=" ls-is-cached lazyloaded"
src="${mov.poster_path}"alt="${mov.original_title}"></div></a><div class="detail"><div class="title">${mov.original_title}</div><div class="info"><span class="type">${mov.year_of_release}</span><span><i class="fa-solid fa-star"></i>${mov.imdb_rating}</span></div></div></div></div>`;return div;}
function openYT(yt,tplus,title){window.open("https://www.youtube.com/watch?v="+yt+(tplus!=undefined?"&t="+tplus:""),'_blank').focus();}
